DELETE FROM champions.pokemon_moves pm
USING champions.pokemon p, champions.moves m, delete_pairs dp
WHERE pm.pokemon_id = p.id
  AND pm.move_id = m.id
  AND p.name_ja = dp.pokemon_name
  AND m.name_ja = dp.move_name;

COMMIT;
